ALTER TABLE public.infection_alerts FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.infection_alerts;
CREATE POLICY tenant_isolation ON public.infection_alerts USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
GRANT SELECT, INSERT, UPDATE ON public.infection_alerts TO orchard_app;
DROP TRIGGER IF EXISTS infection_alerts_touch ON public.infection_alerts;
CREATE TRIGGER infection_alerts_touch BEFORE INSERT OR UPDATE ON public.infection_alerts FOR EACH ROW EXECUTE FUNCTION app.touch_server_updated_at();
DROP TRIGGER IF EXISTS infection_alerts_guard_tenant ON public.infection_alerts;
CREATE TRIGGER infection_alerts_guard_tenant BEFORE UPDATE ON public.infection_alerts FOR EACH ROW EXECUTE FUNCTION app.guard_tenant();

CREATE TABLE IF NOT EXISTS public.weather_daily (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 8 AND 64),
  tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
  orchard_id text NOT NULL,
  day date NOT NULL,
  min_c double precision,
  max_c double precision,
  mean_c double precision,
  precip_mm double precision,
  mean_rh double precision,
  is_forecast boolean,
  hourly jsonb,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  server_updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  deleted_at timestamptz,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, orchard_id) REFERENCES public.orchards(tenant_id, id)
);
ALTER TABLE public.weather_daily OWNER TO orchard_owner;
CREATE INDEX IF NOT EXISTS weather_daily_sync_idx ON public.weather_daily (tenant_id, server_updated_at);
CREATE INDEX IF NOT EXISTS weather_daily_orchard_id_idx ON public.weather_daily (tenant_id, orchard_id);
ALTER TABLE public.weather_daily ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.weather_daily FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.weather_daily;
CREATE POLICY tenant_isolation ON public.weather_daily USING (tenant_id = app.current_tenant()) WITH CHECK (tenant_id = app.current_tenant());
GRANT SELECT, INSERT, UPDATE ON public.weather_daily TO orchard_app;
DROP TRIGGER IF EXISTS weather_daily_touch ON public.weather_daily;
CREATE TRIGGER weather_daily_touch BEFORE INSERT OR UPDATE ON public.weather_daily FOR EACH ROW EXECUTE FUNCTION app.touch_server_updated_at();
DROP TRIGGER IF EXISTS weather_daily_guard_tenant ON public.weather_daily;
CREATE TRIGGER weather_daily_guard_tenant BEFORE UPDATE ON public.weather_daily FOR EACH ROW EXECUTE FUNCTION app.guard_tenant();

